function Pill({ children, tone = "teal" }: { children: ReactNode; tone?: "teal" | "orange" | "purple" | "slate" }) {
  const tones = { teal: "bg-[#e4f5ef] text-[#0c756a]", orange: "bg-[#fff0d8] text-[#9e5e16]", purple: "bg-[#eeedff] text-[#5d59b3]", slate: "bg-[#eef2f2] text-[#60717a]" };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-[.09em] ${tones[tone]}`}>{children}</span>;
}

function PrimaryButton({ children, onClick, href, variant = "primary", className = "", type = "button" }: { children: ReactNode; onClick?: () => void; href?: string; variant?: "primary" | "soft" | "dark" | "outline"; className?: string; type?: "button" | "submit" }) {
  const styles = {
    primary: "bg-[#0b7d80] text-white shadow-[0_9px_24px_rgba(11,125,128,.2)] hover:bg-[#086d70]",
    soft: "bg-[#e5f5ef] text-[#0b706e] hover:bg-[#d5eee6]",
    dark: "bg-[#073b4c] text-white shadow-[0_9px_24px_rgba(7,59,76,.18)] hover:bg-[#0a4d60]",
    outline: "border border-[#cfe0da] bg-white/70 text-[#21575b] hover:bg-white",
  };
  const classes = `pressable focus-ring inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-4 text-sm font-bold transition-colors ${styles[variant]} ${className}`;
  if (href) return <Link href={href} className={classes}>{children}</Link>;
  return <button type={type} onClick={onClick} className={classes}>{children}</button>;
}

