function AdminStat({ value, label, delta, icon: Icon, tone }: { value: string; label: string; delta: string; icon: IconType; tone: "teal" | "purple" | "orange" | "blue" }) { const colors = { teal: "bg-[#e4f5ef] text-[#0b7d80]", purple: "bg-[#eeedff] text-[#625db7]", orange: "bg-[#fff0d8] text-[#a96917]", blue: "bg-[#e7efff] text-[#4165b2]" }; return <div className="soft-card rounded-2xl p-5"><div className="flex items-center justify-between"><span className={`grid size-10 place-items-center rounded-xl ${colors[tone]}`}><Icon size={18} /></span><span className="text-xs font-bold text-[#0b7d80]">{delta}</span></div><p className="mt-5 font-display text-2xl font-semibold text-[#073b4c]">{value}</p><p className="mt-1 text-xs font-bold text-[#64807b]">{label}</p></div>; }
function ReviewItem({ icon: Icon, title, detail, count }: { icon: IconType; title: string; detail: string; count: string }) { return <button className="flex w-full items-center gap-3 rounded-2xl bg-white/60 p-3 text-left transition-colors hover:bg-white"><span className="grid size-9 place-items-center rounded-xl bg-white text-[#625db7]"><Icon size={16} /></span><div className="min-w-0 flex-1"><p className="text-sm font-bold text-[#4b4b82]">{title}</p><p className="mt-0.5 truncate text-xs text-[#8888ad]">{detail}</p></div><span className="text-[10px] font-bold uppercase tracking-[.08em] text-[#625db7]">{count}</span></button>; }
function RankRow({ rank, name, area, score }: { rank: string; name: string; area: string; score: string }) { return <div className="flex items-center gap-3"><span className="font-display text-lg italic text-[#b7b4df]">{rank}</span><span className="grid size-9 place-items-center rounded-xl bg-[#e4f5ef] text-[#0b7d80]"><Store size={16} /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-[#416762]">{name}</p><p className="mt-0.5 text-xs text-[#8da09a]">{area}</p></div><span className="rounded-full bg-[#e4f5ef] px-2 py-1 text-xs font-bold text-[#0b7d80]">{score}</span></div>; }

